/*
# Knowledge Checks (15+ questions per ACORD form)

Generated by supabase/knowledge-checks/build.mjs from supabase/knowledge-checks/questions.mjs — edit the questions there.

Flow per module:  training video (95% watched, server-verified)  ->  Knowledge Check (pass 80%)  ->  PDF assessment.

- Questions and correct answers are staff-only; students receive questions WITHOUT answers via get_knowledge_check().
- submit_knowledge_check() grades on the server. Failed attempts only reveal WHICH questions were wrong;
  the correct answers and explanations are shown once the student passes.
- start_assessment() now refuses to start until the module's Knowledge Check is passed.
*/

-- ============================================================ tables
CREATE TABLE IF NOT EXISTS public.knowledge_check_questions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  module_id text NOT NULL REFERENCES public.acord_modules(id),
  question_key text NOT NULL,
  sort_order integer NOT NULL DEFAULT 0,
  prompt text NOT NULL,
  options jsonb NOT NULL CHECK (jsonb_typeof(options) = 'array' AND jsonb_array_length(options) BETWEEN 2 AND 6),
  correct_index integer NOT NULL CHECK (correct_index >= 0),
  explanation text NOT NULL DEFAULT '',
  is_active boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (module_id, question_key),
  CHECK (correct_index < jsonb_array_length(options))
);
ALTER TABLE public.knowledge_check_questions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.knowledge_check_questions FROM anon;
DROP POLICY IF EXISTS "kc_questions_staff_all" ON public.knowledge_check_questions;
CREATE POLICY "kc_questions_staff_all" ON public.knowledge_check_questions FOR ALL TO authenticated
  USING (public.is_staff()) WITH CHECK (public.is_staff());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.knowledge_check_questions TO authenticated;

CREATE TABLE IF NOT EXISTS public.knowledge_check_attempts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  module_id text NOT NULL REFERENCES public.acord_modules(id),
  score integer NOT NULL,
  correct integer NOT NULL,
  total integer NOT NULL,
  passed boolean NOT NULL,
  answers jsonb NOT NULL DEFAULT '{}'::jsonb,
  results jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_kc_attempts_user_module ON public.knowledge_check_attempts(user_id, module_id, created_at DESC);
ALTER TABLE public.knowledge_check_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.knowledge_check_attempts FROM anon;
DROP POLICY IF EXISTS "kc_attempts_select" ON public.knowledge_check_attempts;
CREATE POLICY "kc_attempts_select" ON public.knowledge_check_attempts FOR SELECT TO authenticated
  USING (user_id = auth.uid() OR public.is_staff());
DROP POLICY IF EXISTS "kc_attempts_staff_delete" ON public.knowledge_check_attempts;
CREATE POLICY "kc_attempts_staff_delete" ON public.knowledge_check_attempts FOR DELETE TO authenticated
  USING (public.is_staff());
GRANT SELECT, DELETE ON public.knowledge_check_attempts TO authenticated;
-- Inserts only happen through submit_knowledge_check() (SECURITY DEFINER).

-- ============================================================ question bank
INSERT INTO public.knowledge_check_questions (module_id, question_key, sort_order, prompt, options, correct_index, explanation)
VALUES
  ('125', 'v_when_used', 1, 'According to the video, when do you use the ACORD 125?', '["Only for workers compensation","Every time you request a commercial insurance quote — business auto, business owners, general liability, property and similar lines","Only when a claim is filed","Only when renewing a personal auto policy"]'::jsonb, 1, 'The 125 is the commercial insurance application you fill out every time you request a quote. (Covered in the training video at 0:21.)'),
  ('125', 'v_date', 2, 'What date goes in the top-right corner of the ACORD 125?', '["The policy expiration date","The insured''s business start date","The date you are filling out the application","The prior policy''s effective date"]'::jsonb, 2, 'The top-right date is the date you fill out the application — the video stresses not to miss this step. (Covered in the training video at 0:34.)'),
  ('125', 'v_every_box', 3, 'Do you need to fill out every box on the ACORD 125?', '["Yes — carriers reject any form with a blank box","No — only the essential fields needed to get a quote from the carrier","Only the boxes on page 1","Only the boxes the insured fills out"]'::jsonb, 1, 'Fill out the fields that are necessary to get a quote, not every single box. (Covered in the training video at 0:55.)'),
  ('125', 'v_contact_accuracy', 4, 'Why must your agency contact name, phone and e-mail be accurate?', '["They are printed on the insured''s ID cards","Carriers use them to ask for more information and to send the quote details","They determine the premium","They are only for the agency''s records"]'::jsonb, 1, 'Carriers contact you there and send the quote there — errors mean missed communications. (Covered in the training video at 1:27.)'),
  ('125', 'v_effective_date', 5, 'What does the video recommend for the proposed effective date?', '["Today''s date","At least one week in advance","Exactly 30 days in advance","The first day of next year"]'::jsonb, 1, 'Some carriers answer in a day, others take a few days, so give yourself at least a week. (Covered in the training video at 1:52.)'),
  ('125', 'v_expiration', 6, 'How is the proposed expiration date set?', '["Six months from the effective date","One calendar year from the proposed effective date","The same as the prior policy''s expiration","The carrier fills it in"]'::jsonb, 1, 'The proposed expiration date is always one calendar year from the proposed effective date. (Covered in the training video at 2:12.)'),
  ('125', 'v_direct_bill', 7, 'What does selecting the "Direct" billing plan mean?', '["The agency bills the insured","The carrier bills the applicant/insured directly, not the agency","The premium is paid in full up front","The insured pays the producer in cash"]'::jsonb, 1, 'Direct bill = the carrier bills the insured directly. (Covered in the training video at 2:22.)'),
  ('125', 'v_payment_audit', 8, 'In the video''s example, what do the payment plan "M" and audit "A" stand for?', '["Mortgagee / Agency","Monthly payments / Annual audit","Minimum premium / Additional insured","Manual rating / Automatic renewal"]'::jsonb, 1, 'M = monthly payment plan (always check if it is available); A = annual audit, usually done when the policy comes up for renewal. (Covered in the training video at 2:38.)'),
  ('125', 'v_sole_prop', 9, 'The applicant is a sole proprietor with no LLC or corporation. How is the applicant name entered?', '["Only the business name","Their first and last name \"doing business as\" (DBA) the business name","The agency''s name","Leave it blank"]'::jsonb, 1, 'With no entity, enter the owner''s name DBA the business name. With an entity, enter the entity name (e.g. "… LLC"). (Covered in the training video at 3:10.)'),
  ('125', 'v_ein', 10, 'Why is the EIN box so important on the ACORD 125?', '["It is optional and rarely used","Without it, carriers will not be able to generate a quote — if the client has no EIN, use their Social Security number","It is only needed for non-profits","It replaces the business phone number"]'::jsonb, 1, 'The video calls the EIN crucial: no EIN (or SSN if there is no EIN) means no quote. (Covered in the training video at 3:38.)'),
  ('125', 'v_location_building', 11, 'The business has a main building and a storage shed at the same address. How is the shed numbered?', '["Location 2, Building 1","Location 1, Building 2","Location 2, Building 2","It is not listed"]'::jsonb, 1, 'Same address = same location number (1); the second structure is Building 2. A different address would be Location 2, Building 1. (Covered in the training video at 4:36.)'),
  ('125', 'v_employee_count', 12, 'The employee counts in the premises section refer to:', '["All employees across every location","Only the employees working at that specific location","Only the owners","Only part-time employees"]'::jsonb, 1, 'Employee counts (full-time and part-time) are only for that location. (Covered in the training video at 5:20.)'),
  ('125', 'v_total_area', 13, 'The business rents a unit in a strip mall. What goes in "total building area"?', '["Only the insured''s unit","The square footage of the entire building, including spaces leased by other businesses","The parking lot area","Leave it blank"]'::jsonb, 1, 'Total building area is the whole building; the insured''s own space and public area are entered separately. (Covered in the training video at 6:30.)'),
  ('125', 'v_yes_answers', 14, 'How should you handle the general information (yes/no) questions?', '["Answer them yourself based on the business type","Ask the insured every question word for word, and give a brief explanation for any \"yes\" answer","Skip them for small businesses","Answer \"no\" to all of them to speed up the quote"]'::jsonb, 1, 'Ask each question word for word and explain every "yes". (Covered in the training video at 8:20.)'),
  ('125', 'v_signature', 15, 'Does the applicant have to sign the ACORD 125 to get a quote?', '["Yes — no quote without a signature","No — a signature is not needed to quote, but it is required before binding, and the dates are updated to the binding date","Only the producer signs","Only for policies over $1M"]'::jsonb, 1, 'Signature is not required to quote; it is required to bind, and the effective/expiration dates are updated to the date of binding. (Covered in the training video at 11:05.)'),
  ('126', 'v_with_125', 1, 'The ACORD 126 is filled out together with which form to get a general liability quote?', '["ACORD 25","ACORD 125","ACORD 130","ACORD 140"]'::jsonb, 1, 'The 126 (Commercial General Liability section) is filled out with the ACORD 125. (Covered in the training video at 0:06.)'),
  ('126', 'v_occurrence', 2, 'On an occurrence policy, which carrier is responsible for a claim?', '["The carrier providing coverage when the claim is made","The carrier providing coverage at the time of the occurrence (incident)","The carrier with the lowest premium","The agency"]'::jsonb, 1, 'Occurrence: the carrier on the risk when the incident happened is liable. (Covered in the training video at 1:17.)'),
  ('126', 'v_claims_made', 3, 'On a claims-made policy, which carrier is responsible?', '["The carrier providing coverage at the time the claim is made — even if the incident happened earlier","The carrier that wrote the first policy","The carrier at the time of the incident only","No carrier"]'::jsonb, 0, 'Claims-made: the carrier on the risk when the claim is made is liable. (Covered in the training video at 1:31.)'),
  ('126', 'v_limits', 4, 'The video''s standard GL limits are "2 million / 1 million". What do they mean?', '["$2M each occurrence / $1M aggregate","Up to $2M for the year (general aggregate) and up to $1M for any single incident (each occurrence)","$2M deductible / $1M premium","$2M property / $1M liability"]'::jsonb, 1, 'General aggregate $2,000,000 for the policy year; each occurrence $1,000,000 per incident. (Covered in the training video at 1:56.)'),
  ('126', 'v_completed_ops', 5, 'Why is products/completed operations coverage especially important for contractors and service businesses?', '["It covers their tools while in the truck","It gives them coverage after they leave the job site","It pays employee wages","It covers their own building"]'::jsonb, 1, 'Their "premises" is the job site while they work there; completed operations covers them after they leave. (Covered in the training video at 2:45.)'),
  ('126', 'v_pai', 6, 'Personal and advertising injury coverage applies to:', '["Physical injuries on the premises","Injury other than physical — e.g. another business losing income because of something said about it (slander)","Damage to rented equipment","Vehicle accidents"]'::jsonb, 1, 'It covers non-physical injury such as slander or libel. (Covered in the training video at 3:04.)'),
  ('126', 'v_pai_limit', 7, 'What is a typical personal and advertising injury limit according to the video?', '["$10,000","$1 million, or half of the general aggregate","Equal to the deductible","Twice the general aggregate"]'::jsonb, 1, 'A standard is typically $1,000,000 — half of the general aggregate. (Covered in the training video at 3:24.)'),
  ('126', 'v_rented', 8, 'Damage to rented premises covers:', '["Property that is rented to the insured — e.g. a leased building or leased equipment","Property the insured rents out to others","The insured''s own vehicles","Customers'' cars"]'::jsonb, 0, 'It covers damage to property that is rented or leased to the insured. (Covered in the training video at 3:34.)'),
  ('126', 'v_med_exp', 9, 'What does the medical expense coverage do?', '["Pays the insured''s employees'' health insurance","Pays for bodily injury to a third party up to a limit without having to go to court","Pays the owner''s hospital bills","Pays only after a lawsuit"]'::jsonb, 1, 'Medical expense pays third-party bodily injury up to its limit without going to court. (Covered in the training video at 3:43.)'),
  ('126', 'v_hnoa', 10, 'Hired and non-owned auto (listed under "other coverages") covers:', '["Company-owned trucks","Liability when an employee or the owner uses a personal vehicle for business purposes","Rental reimbursement","Theft of a personal vehicle"]'::jsonb, 1, 'The personal auto policy likely won''t pay for business use, so hired and non-owned auto covers that liability. (Covered in the training video at 4:10.)'),
  ('126', 'v_class_code', 11, 'In the schedule of hazards, is the class code required according to the video?', '["Yes — the quote is rejected without it","No — you do not have to put the class code; the premium basis and exposure are what you fill out","Only for restaurants","Only for claims-made policies"]'::jsonb, 1, 'You don''t have to enter the class code; fill in the premium basis and the exposure. (Covered in the training video at 5:01.)'),
  ('126', 'v_basis_default', 12, '"When all else fails", which premium basis does the video say to use?', '["Payroll","Area","Sales (S)","Units"]'::jsonb, 2, 'Sales can be used as a standard for any quote — e.g. S with $150,000 gross sales. (Covered in the training video at 5:07.)'),
  ('126', 'v_basis_other', 13, 'Which premium basis matches each business type, according to the video?', '["Apartment/hotel = payroll; contractor = units; landlord = sales","Apartment/hotel = units; contractor = payroll; landlord = area (per 1,000 sq ft)","All of them use sales","Apartment/hotel = area; contractor = sales; landlord = units"]'::jsonb, 1, 'Units for apartments/hotels, payroll for contractors, area per 1,000 sq ft for landlords — otherwise sales. (Covered in the training video at 5:24.)'),
  ('126', 'v_sections_skip', 14, 'When do you fill out the Contractors section and the Products/Completed Operations section?', '["Always, for every business","Contractors section only if they subcontract work; products section only if they make and sell products — service businesses can skip it","Never — the underwriter completes them","Only for claims-made policies"]'::jsonb, 1, 'Fill those sections only when they apply; general information questions must be answered for every business. (Covered in the training video at 6:32.)'),
  ('126', 'v_general_info', 15, 'How are the general information questions on the 126 handled?', '["They are optional","They must be answered for every business, with a brief explanation for any \"yes\" answer","Only contractors answer them","They are answered by the carrier"]'::jsonb, 1, 'General information questions are required regardless of business type; explain each "yes". (Covered in the training video at 7:27.)'),
  ('127', 'v_what', 1, 'What is the ACORD 127?', '["The Business Auto section of a commercial application","A personal auto ID card","The Property section","The Workers Compensation application"]'::jsonb, 0, 'The video covers completing the Business Auto Section, ACORD 127. (Covered in the training video at 0:00.)'),
  ('127', 'v_agency', 2, 'What goes in the agency box?', '["The insurance carrier''s name","The name of the agency/business you work for","The insured''s business name","The underwriter''s name"]'::jsonb, 1, 'The agency is whatever business you are working for, e.g. "Sales Insurance Agency". (Covered in the training video at 0:15.)'),
  ('127', 'v_carrier_blank', 3, 'For a brand-new quote, what do you do with the Carrier and NAIC code boxes?', '["Guess the most likely carrier","Leave them blank — on new quotes you often don''t have a carrier yet","Enter the prior carrier","Enter \"TBD\" and the agency NAIC"]'::jsonb, 1, 'The carrier isn''t important yet on a new quote, so carrier and NAIC code can be left blank. (Covered in the training video at 0:26.)'),
  ('127', 'v_customer_id', 4, 'When is the Agency Customer ID used?', '["On every new customer","When you already have the customer — e.g. as a broker re-shopping them for a better rate","Only for fleets over 10 vehicles","It is the insured''s FEIN"]'::jsonb, 1, 'Customer ID applies to existing customers; for a brand-new customer you don''t need it. (Covered in the training video at 0:39.)'),
  ('127', 'v_date', 5, 'What date goes at the top of the ACORD 127?', '["The policy expiration date","The day you are writing the quote","The insured''s birthday","The date of the last claim"]'::jsonb, 1, 'The date is the day you are actually writing the quote. (Covered in the training video at 0:58.)'),
  ('127', 'v_policy_number', 6, 'When do you enter a policy number?', '["Always — make one up if needed","When you have the customer or know the number from their previous policy","Only after binding","Never on the 127"]'::jsonb, 1, 'Enter it if you have the customer or know their previous policy number. (Covered in the training video at 1:06.)'),
  ('127', 'v_named_insured', 7, 'There is more than one named insured. What do you do?', '["List only the first one","Put down the information for each named insured","List them in remarks only","Choose the owner"]'::jsonb, 1, 'Sometimes there is more than one named insured — list each one. (Covered in the training video at 1:15.)'),
  ('127', 'v_driver_info', 8, 'What "pedigree" information is collected for each driver?', '["Only the driver''s first name","Driver details such as name, address (city, state, ZIP), sex, date of birth and license information","Only the license plate","The driver''s salary"]'::jsonb, 1, 'Each driver gets full pedigree information; list every driver. (Covered in the training video at 1:32.)'),
  ('127', 'v_163', 9, 'Which ACORD form is the commercial auto driver information schedule used along with the 127?', '["ACORD 25","ACORD 163","ACORD 140","ACORD 130"]'::jsonb, 1, 'The video says you need the 127 and the ACORD 163 (driver information) as well. (Covered in the training video at 1:20.)'),
  ('127', 'v_questions', 10, 'Who answers the yes/no questions (e.g. "vehicle maintenance program in operation?", "any vehicles leased to others?")?', '["You answer them based on your best guess","You ask the driver or the company every question","The carrier","They are optional"]'::jsonb, 1, 'All the yes/no questions are asked of the insured company or driver. (Covered in the training video at 1:51.)'),
  ('127', 'v_telematics', 11, 'Question 17 asks about an electronic monitoring device that records and transmits vehicle data. Why does it matter?', '["It is required by law","Having one can get the insured a discounted rate","It increases the premium","It replaces the driver schedule"]'::jsonb, 1, 'Electronic monitoring (e.g. built-in navigation, maintenance monitoring) can earn a discount. (Covered in the training video at 2:12.)'),
  ('127', 'v_addl_interest', 12, 'When is the additional interest section filled out?', '["Never","When a vehicle is leased/financed or there is an additional insured","Only for drivers under 25","Only for trailers"]'::jsonb, 1, 'Leasing or an additional insured means you list the additional interest; otherwise leave it blank. (Covered in the training video at 2:26.)'),
  ('127', 'v_remarks', 13, 'What is the Remarks section (ACORD 101) used for?', '["The insured''s signature","A comment section to tell the underwriter any specific details about the insured or vehicles","Listing the premium","The carrier''s decision"]'::jsonb, 1, 'Remarks are like a comment section for the underwriter. (Covered in the training video at 2:45.)'),
  ('127', 'v_129', 14, 'There are more vehicles than fit on the form. Which form is attached for the additional vehicles?', '["ACORD 101","ACORD 129 (vehicle schedule)","ACORD 163","ACORD 126"]'::jsonb, 1, 'Attach the ACORD 129 for additional vehicles. (Covered in the training video at 3:00.)'),
  ('127', 'v_vehicle_info', 15, 'Which vehicle details does the video say must be filled out?', '["Only the color","Year, make, model and body type (e.g. 2018 Toyota Camry), vehicle type, garaging address and how the vehicle is used","Only the license plate","Only the purchase price"]'::jsonb, 1, 'Each vehicle needs year/make/model/body type, type, garaging address and use (pleasure, farm, service, commercial). (Covered in the training video at 3:09.)'),
  ('130', 'v_agency', 1, 'Which agency details does the video say to fill out on the ACORD 130?', '["Only the agency''s tax ID","Agency name and address, producer name, office phone and e-mail (cell, fax and CSR name are optional)","The underwriter''s name and phone","Nothing — the carrier fills in the agency section"]'::jsonb, 1, 'Agency name/address, producer name, office phone and e-mail; you can add a cell, fax or customer service rep if you like. (Covered in the training video at 0:17.)'),
  ('130', 'v_company_uw', 2, 'On the right-hand side, which fields are NOT needed to get a quote?', '["Applicant name","Company and underwriter","Applicant office phone","Mailing address"]'::jsonb, 1, 'You do not need to put the company or underwriter, but you do need the applicant name. (Covered in the training video at 0:43.)'),
  ('130', 'v_sic_naics', 3, 'What does the video say about SIC/NAICS codes and the website?', '["All are required to get a quote","You do not need SIC or NAICS; a website is good to include but not required for a quote","Only the NAICS code is required","The website is required"]'::jsonb, 1, 'SIC and NAICS are not needed; a website is always good to include but not required. (Covered in the training video at 0:55.)'),
  ('130', 'v_zip4', 4, 'The mailing address asks for ZIP+4. Do you need it for a quote?', '["Yes, the quote is rejected without it","No — you don''t need the additional four digits for the quote","Only for Canadian addresses","Only for P.O. boxes"]'::jsonb, 1, 'The form asks for ZIP+4, but it is not needed to get a quote. (Covered in the training video at 1:09.)'),
  ('130', 'v_fein', 5, 'Which identification number does the video say you really need to get a WC quote?', '["The NCCI risk ID number","The Federal Employer ID Number (FEIN)","The agency customer ID","The SIC code"]'::jsonb, 1, 'You do not need the NCCI risk ID; what you need to get a quote is the federal ID number. (Covered in the training video at 1:25.)'),
  ('130', 'v_billing', 6, 'Which billing plan is most common for workers comp, according to the video?', '["Agency bill","Direct bill","Premium finance","Monthly self-reporting only"]'::jsonb, 1, 'Choose direct or agency bill — most work comp is direct bill. Then pick annual, semi-annual or quarterly payment. (Covered in the training video at 1:46.)'),
  ('130', 'v_home_location', 7, 'An employee works from home. What should you do in the Locations section?', '["Nothing — home offices are never listed","Add the home location as well, for work comp","List it only in remarks","Exclude that employee"]'::jsonb, 1, 'List all locations — if someone works from home, add that location too for work comp. (Covered in the training video at 2:19.)'),
  ('130', 'v_states', 8, 'Where do the states the insured operates in go?', '["Only in the mailing address","Part 1 lists the work comp states they operate in; any other states they operate in are listed separately (other states)","In the remarks section only","They are not needed"]'::jsonb, 1, 'Part 1 = states they operate in (with the employer''s liability limits); list any other states they operate in as well. (Covered in the training video at 2:35.)'),
  ('130', 'v_contacts', 9, 'Do you need the inspection / accounting records / claims contacts when you also submit an ACORD 125?', '["Yes, always — the quote fails without them","Not required if submitting with the ACORD 125, but filling them out keeps the application complete","Only the claims contact","They must be three different people"]'::jsonb, 1, 'They are not needed with a 125, but the presenter fills them in anyway so the form is complete. (Covered in the training video at 2:50.)'),
  ('130', 'v_inc_exc', 10, 'Who must be listed in the "Individuals included/excluded" section?', '["Only the majority owner","Partners, officers and relatives employed by the business — each must be either included or excluded (list every owner)","All employees","Only excluded people"]'::jsonb, 1, 'Every partner, officer or employed relative is listed as included or excluded — if there are two owners, list both. (Covered in the training video at 3:17.)'),
  ('130', 'v_included_class', 11, 'An owner is marked "Included". What else must you add for that person?', '["Nothing else","Their class code and payroll","Their Social Security number","Their home address"]'::jsonb, 1, 'Included individuals need a class code and payroll listed. (Covered in the training video at 3:48.)'),
  ('130', 'v_rating_worksheet', 12, 'How is the State Rating Worksheet completed?', '["One line for the whole company","A separate class code line for each type of job/duty, with full-time/part-time employee counts and payroll","Only the highest-rated class","Only clerical employees"]'::jsonb, 1, 'Each duty gets its own class code, employee counts and payroll — e.g. a clerical employee gets the lower-rated clerical class. (Covered in the training video at 4:06.)'),
  ('130', 'v_ncci', 13, 'How does the video recommend confirming the correct class code?', '["Guess based on the business name","Call NCCI — they will give you the correct class code at no charge","Use the GL class code","Ask the insured to pick one"]'::jsonb, 1, 'Always call NCCI to get the correct class code before sending it in. (Covered in the training video at 4:51.)'),
  ('130', 'v_loss_history', 14, 'What does the video say about prior carrier and loss history?', '["Only the last year is needed","Include the past five years: year, company, policy number, premium, mod, number of claims, and amount paid — open claims go under reserve","Leave it blank if there were losses","Only list claims over $50,000"]'::jsonb, 1, 'Five years of history; amounts on open claims go under reserve, closed claims under amount paid. You can also attach the loss runs. (Covered in the training video at 5:38.)'),
  ('130', 'v_signature', 15, 'What is needed when you go to bind the WC policy?', '["Nothing — the quote is enough","The applicant''s signature, your signature, the date, and your national producer number","Only the insured''s initials","Only the NCCI risk ID"]'::jsonb, 1, 'A signature is not needed to quote, but to bind you need the applicant''s and producer''s signatures, the date and the national producer number. (Covered in the training video at 9:26.)'),
  ('140', 'v_location_only', 1, 'A contractor carries tools and equipment away from their primary location. Does the ACORD 140 property coverage cover them?', '["Yes, anywhere in the country","No — 140 property coverage is limited to the location (about 1,000 feet around it); tools taken away need an inland marine policy","Only if they are in a vehicle","Only on weekends"]'::jsonb, 1, 'Property coverage is limited to the location; mobile equipment belongs on inland marine. (Covered in the training video at 0:09.)'),
  ('140', 'v_with_125', 2, 'Can you get a quote with the ACORD 140 by itself?', '["Yes","No — it must be filled out along with the ACORD 125","Only for buildings under 5,000 sq ft","Only with the ACORD 127"]'::jsonb, 1, 'The 140 has to be submitted with the 125 commercial insurance application. (Covered in the training video at 0:40.)'),
  ('140', 'v_premises_numbering', 3, 'A second building at the same address is entered as:', '["Premises 2, Building 1","Premises (location) 1, Building 2","Premises 2, Building 2","It is not entered"]'::jsonb, 1, 'Same address keeps premises 1 and moves to building 2; a new address is premises 2, building 1. (Covered in the training video at 3:05.)'),
  ('140', 'v_subjects', 4, 'What are the two subject-of-insurance options the video uses?', '["Liability and auto","Building and Business Personal Property (BPP)","Flood and earthquake","Payroll and sales"]'::jsonb, 1, 'Subject of insurance: Building, and Business Personal Property (BPP). (Covered in the training video at 3:57.)'),
  ('140', 'v_tenant', 5, 'The insured leases its space and does not own the building. Which coverage do you remove?', '["Business personal property","Building coverage — they only need BPP","Business income","Both"]'::jsonb, 1, 'If they rent or lease, they don''t need building coverage — only business personal property. (Covered in the training video at 4:19.)'),
  ('140', 'v_estimate', 6, 'Without a cost evaluator, how does the video estimate the building value of a 4,000 sq ft building?', '["$50 × square footage = $200,000","$120 × square footage = $480,000","Use the purchase price","Use the insured''s annual revenue"]'::jsonb, 1, 'A ballpark figure is $120 multiplied by the square footage: 120 × 4,000 = $480,000. (Covered in the training video at 4:44.)'),
  ('140', 'v_coinsurance', 7, 'What coinsurance percentage does the video call the "magic number"?', '["50%","70%","80%","100%"]'::jsonb, 2, '80% coinsurance — the amount of insurance is at least 80% of the building''s value. (Covered in the training video at 5:09.)'),
  ('140', 'v_rcv', 8, 'What does "RCV" stand for in the valuation box?', '["Real cash value","Replacement cost value","Recorded current value","Rental contract value"]'::jsonb, 1, 'RCV = replacement cost value. (Covered in the training video at 5:30.)'),
  ('140', 'v_special', 9, 'Which cause of loss does the video select, and why?', '["Basic — it is the cheapest","Special — the broadest form of coverage available","Broad — it is required by law","Named perils — it covers floods"]'::jsonb, 1, 'Special is the broadest form of coverage available. (Covered in the training video at 5:36.)'),
  ('140', 'v_inflation_guard', 10, 'What does a 7–8% inflation guard do?', '["Lowers the premium each year","Increases the amount of coverage by that percentage at renewal to keep up with inflation","Sets the deductible","Adds earthquake coverage"]'::jsonb, 1, 'Inflation guard raises the amount at each renewal (e.g. 7%) to keep pace with inflation. (Covered in the training video at 5:42.)'),
  ('140', 'v_deductible', 11, 'What does the video say about the deductible?', '["It is always $10,000","It is not required unless the client specifies one; $1,000 is a good common standard","It must equal the coinsurance %","It is set by the agency"]'::jsonb, 1, 'Fill it in if the client asks; $1,000 is a common standard. (Covered in the training video at 6:02.)'),
  ('140', 'v_bpp', 12, 'Business personal property (contents) includes:', '["The building itself","Anything the business owns that is not the building or physically attached/bolted to it","Only inventory for sale","Employees'' personal belongings"]'::jsonb, 1, 'BPP is everything the business owns that is not the building or attached to it. (Covered in the training video at 6:19.)'),
  ('140', 'v_business_income', 13, 'What does the video say about the Business Income box?', '["Leave it unchecked unless the insured has employees","Always check it — it pays expenses such as utility bills and key employee salaries while the business is shut down by a covered loss","It covers lost customers after a bad review","It only applies to restaurants"]'::jsonb, 1, 'We always want to check business income. (Covered in the training video at 7:00.)'),
  ('140', 'v_construction', 14, 'Which construction types does the video say are usual?', '["Steel, glass and concrete","Frame, masonry, or joisted masonry","Brick only","Modular and mobile"]'::jsonb, 1, 'There are usually three: frame, masonry or joisted masonry. (Covered in the training video at 8:33.)'),
  ('140', 'v_alarms', 15, 'What is the difference between a "central station" and a "local gong" alarm?', '["There is no difference","Central station contacts and notifies the authorities; local gong only makes noise at the location","Local gong calls the police; central station only makes noise","Central station is for fire only"]'::jsonb, 1, 'Central station notifies authorities so help is dispatched; local gong just sounds an alarm. If there is no alarm, enter "None". (Covered in the training video at 11:00.)')
ON CONFLICT (module_id, question_key) DO UPDATE SET
  sort_order = EXCLUDED.sort_order, prompt = EXCLUDED.prompt, options = EXCLUDED.options,
  correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, is_active = true, updated_at = now();

-- Questions removed from questions.mjs are retired (kept for attempt history).
UPDATE public.knowledge_check_questions SET is_active = false, updated_at = now()
WHERE (module_id, question_key) NOT IN (('125', 'v_when_used'), ('125', 'v_date'), ('125', 'v_every_box'), ('125', 'v_contact_accuracy'), ('125', 'v_effective_date'), ('125', 'v_expiration'), ('125', 'v_direct_bill'), ('125', 'v_payment_audit'), ('125', 'v_sole_prop'), ('125', 'v_ein'), ('125', 'v_location_building'), ('125', 'v_employee_count'), ('125', 'v_total_area'), ('125', 'v_yes_answers'), ('125', 'v_signature'), ('126', 'v_with_125'), ('126', 'v_occurrence'), ('126', 'v_claims_made'), ('126', 'v_limits'), ('126', 'v_completed_ops'), ('126', 'v_pai'), ('126', 'v_pai_limit'), ('126', 'v_rented'), ('126', 'v_med_exp'), ('126', 'v_hnoa'), ('126', 'v_class_code'), ('126', 'v_basis_default'), ('126', 'v_basis_other'), ('126', 'v_sections_skip'), ('126', 'v_general_info'), ('127', 'v_what'), ('127', 'v_agency'), ('127', 'v_carrier_blank'), ('127', 'v_customer_id'), ('127', 'v_date'), ('127', 'v_policy_number'), ('127', 'v_named_insured'), ('127', 'v_driver_info'), ('127', 'v_163'), ('127', 'v_questions'), ('127', 'v_telematics'), ('127', 'v_addl_interest'), ('127', 'v_remarks'), ('127', 'v_129'), ('127', 'v_vehicle_info'), ('130', 'v_agency'), ('130', 'v_company_uw'), ('130', 'v_sic_naics'), ('130', 'v_zip4'), ('130', 'v_fein'), ('130', 'v_billing'), ('130', 'v_home_location'), ('130', 'v_states'), ('130', 'v_contacts'), ('130', 'v_inc_exc'), ('130', 'v_included_class'), ('130', 'v_rating_worksheet'), ('130', 'v_ncci'), ('130', 'v_loss_history'), ('130', 'v_signature'), ('140', 'v_location_only'), ('140', 'v_with_125'), ('140', 'v_premises_numbering'), ('140', 'v_subjects'), ('140', 'v_tenant'), ('140', 'v_estimate'), ('140', 'v_coinsurance'), ('140', 'v_rcv'), ('140', 'v_special'), ('140', 'v_inflation_guard'), ('140', 'v_deductible'), ('140', 'v_bpp'), ('140', 'v_business_income'), ('140', 'v_construction'), ('140', 'v_alarms'));

-- ============================================================ helpers
CREATE OR REPLACE FUNCTION lava_private.module_videos_complete(p_uid uuid, p_module_id text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM public.training_materials WHERE module_id = p_module_id AND material_type = 'video' AND is_current)
     AND NOT EXISTS (
       SELECT 1 FROM public.training_materials t
       LEFT JOIN public.video_progress vp ON vp.asset_key = t.asset_key AND vp.user_id = p_uid
       WHERE t.module_id = p_module_id AND t.material_type = 'video' AND t.is_current AND t.is_required
         AND coalesce(vp.completed, false) = false)
$$;
REVOKE EXECUTE ON FUNCTION lava_private.module_videos_complete(uuid, text) FROM PUBLIC, anon, authenticated;

-- ============================================================ student RPCs
-- Status + questions (without answers). Questions are only returned once the video is complete and the check is not yet passed.
CREATE OR REPLACE FUNCTION public.get_knowledge_check(p_module_id text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_count integer;
  v_video boolean;
  v_passed boolean;
  v_best integer;
  v_attempts integer;
  v_last jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  SELECT count(*) INTO v_count FROM public.knowledge_check_questions WHERE module_id = p_module_id AND is_active;
  v_video := lava_private.module_videos_complete(v_uid, p_module_id);
  SELECT coalesce(bool_or(passed), false), max(score), count(*) INTO v_passed, v_best, v_attempts
    FROM public.knowledge_check_attempts WHERE user_id = v_uid AND module_id = p_module_id;
  SELECT jsonb_build_object('score', score, 'correct', correct, 'total', total, 'passed', passed, 'created_at', created_at,
           'results', CASE WHEN passed THEN results ELSE '[]'::jsonb END)
    INTO v_last FROM public.knowledge_check_attempts
    WHERE user_id = v_uid AND module_id = p_module_id ORDER BY passed DESC, created_at DESC LIMIT 1;

  RETURN jsonb_build_object(
    'question_count', v_count,
    'pass_score', 80,
    'video_complete', v_video,
    'passed', v_passed,
    'best_score', v_best,
    'attempts', v_attempts,
    'last_attempt', v_last,
    'questions', CASE WHEN v_video AND NOT v_passed AND v_count > 0 THEN (
      SELECT jsonb_agg(jsonb_build_object('id', id, 'prompt', prompt, 'options', options) ORDER BY sort_order)
      FROM public.knowledge_check_questions WHERE module_id = p_module_id AND is_active) ELSE '[]'::jsonb END);
END $$;

-- p_answers: { "<question id>": <chosen option index>, ... }
CREATE OR REPLACE FUNCTION public.submit_knowledge_check(p_module_id text, p_answers jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_uid uuid := auth.uid();
  qrow record;
  v_given integer;
  v_ok boolean;
  v_correct integer := 0;
  v_total integer := 0;
  v_score integer;
  v_passed boolean;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  IF p_answers IS NULL OR jsonb_typeof(p_answers) <> 'object' THEN RAISE EXCEPTION 'INVALID_VALUES'; END IF;
  IF NOT lava_private.module_videos_complete(v_uid, p_module_id) THEN RAISE EXCEPTION 'VIDEO_INCOMPLETE'; END IF;
  IF EXISTS (SELECT 1 FROM public.knowledge_check_attempts WHERE user_id = v_uid AND module_id = p_module_id AND passed) THEN
    RAISE EXCEPTION 'KNOWLEDGE_CHECK_ALREADY_PASSED';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('kc:' || v_uid::text || ':' || p_module_id));

  FOR qrow IN SELECT * FROM public.knowledge_check_questions WHERE module_id = p_module_id AND is_active ORDER BY sort_order LOOP
    v_total := v_total + 1;
    v_given := CASE WHEN jsonb_typeof(p_answers -> qrow.id::text) = 'number' THEN (p_answers ->> qrow.id::text)::integer END;
    v_ok := v_given IS NOT NULL AND v_given = qrow.correct_index;
    IF v_ok THEN v_correct := v_correct + 1; END IF;
    v_results := v_results || jsonb_build_array(jsonb_build_object(
      'id', qrow.id, 'prompt', qrow.prompt, 'options', qrow.options, 'given', v_given, 'correct', v_ok,
      'correct_index', qrow.correct_index, 'explanation', qrow.explanation));
  END LOOP;
  IF v_total = 0 THEN RAISE EXCEPTION 'KNOWLEDGE_CHECK_NOT_FOUND'; END IF;

  v_score := round(v_correct * 100.0 / v_total);
  v_passed := v_score >= 80;
  INSERT INTO public.knowledge_check_attempts (user_id, module_id, score, correct, total, passed, answers, results)
  VALUES (v_uid, p_module_id, v_score, v_correct, v_total, v_passed, p_answers, v_results);

  RETURN jsonb_build_object('score', v_score, 'correct', v_correct, 'total', v_total, 'passed', v_passed, 'pass_score', 80,
    -- Before passing, only reveal which questions were wrong — not the right answers.
    'results', CASE WHEN v_passed THEN v_results ELSE (
      SELECT coalesce(jsonb_agg(jsonb_build_object('id', r->'id', 'prompt', r->'prompt', 'given', r->'given', 'correct', r->'correct')), '[]'::jsonb)
      FROM jsonb_array_elements(v_results) r) END);
END $$;

-- Staff: let a student retake a passed check (e.g. after the video or questions change).
CREATE OR REPLACE FUNCTION public.staff_reset_knowledge_check(p_user_id uuid, p_module_id text) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE n integer;
BEGIN
  IF NOT public.is_staff() THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  DELETE FROM public.knowledge_check_attempts WHERE user_id = p_user_id AND module_id = p_module_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- ============================================================ assessment gate
CREATE OR REPLACE FUNCTION public.start_assessment(p_module_id text) RETURNS public.assessment_attempts
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_pdf public.training_materials;
  v_attempt public.assessment_attempts;
  v_used integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.acord_modules WHERE id = p_module_id) THEN RAISE EXCEPTION 'MODULE_NOT_FOUND'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext(v_uid::text || ':' || p_module_id));

  -- Resume an attempt already in progress.
  SELECT * INTO v_attempt FROM public.assessment_attempts
    WHERE user_id = v_uid AND module_id = p_module_id AND status = 'in_progress';
  IF v_attempt.id IS NOT NULL THEN RETURN v_attempt; END IF;

  -- Video gate: at least one current video, and every required current video completed.
  IF NOT EXISTS (SELECT 1 FROM public.training_materials WHERE module_id = p_module_id AND material_type = 'video' AND is_current) THEN
    RAISE EXCEPTION 'NO_VIDEO';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.training_materials t
    LEFT JOIN public.video_progress vp ON vp.asset_key = t.asset_key AND vp.user_id = v_uid
    WHERE t.module_id = p_module_id AND t.material_type = 'video' AND t.is_current AND t.is_required
      AND coalesce(vp.completed, false) = false) THEN
    RAISE EXCEPTION 'VIDEO_INCOMPLETE';
  END IF;

  -- Knowledge Check gate: the module's quiz must be passed before the PDF assessment.
  IF EXISTS (SELECT 1 FROM public.knowledge_check_questions WHERE module_id = p_module_id AND is_active)
     AND NOT EXISTS (SELECT 1 FROM public.knowledge_check_attempts WHERE user_id = v_uid AND module_id = p_module_id AND passed) THEN
    RAISE EXCEPTION 'KNOWLEDGE_CHECK_NOT_PASSED';
  END IF;

  SELECT * INTO v_pdf FROM public.training_materials WHERE module_id = p_module_id AND material_type = 'pdf' AND is_current;
  IF v_pdf.id IS NULL THEN RAISE EXCEPTION 'NO_PDF'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.pdf_form_fields WHERE material_id = v_pdf.id AND field_type NOT IN ('button', 'signature')) THEN
    RAISE EXCEPTION 'PDF_NOT_FILLABLE';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.pdf_field_mappings WHERE material_id = v_pdf.id AND is_scored AND points > 0
                   AND (coalesce(expected_value, '') <> '' OR match_type = 'present' OR missing_rule = 'expect_blank')) THEN
    RAISE EXCEPTION 'GRADING_NOT_CONFIGURED';
  END IF;

  SELECT count(*) INTO v_used FROM public.assessment_attempts WHERE user_id = v_uid AND module_id = p_module_id AND status = 'submitted';
  IF v_used >= 3 THEN RAISE EXCEPTION 'NO_ATTEMPTS_REMAINING'; END IF;

  INSERT INTO public.assessment_attempts (user_id, module_id, material_id, student_name, attempt_number, status, started_at,
      score, correct, incorrect, missing, total_fields, completion_time_min, field_values, field_results, completed_at)
  VALUES (v_uid, p_module_id, v_pdf.id, coalesce((SELECT NULLIF(full_name, '') FROM public.profiles WHERE id = v_uid), 'Trainee'),
      v_used + 1, 'in_progress', now(), 0, 0, 0, 0, 0, 0, '{}'::jsonb, '[]'::jsonb, NULL)
  RETURNING * INTO v_attempt;
  RETURN v_attempt;
END $$;

REVOKE EXECUTE ON FUNCTION public.get_knowledge_check(text), public.submit_knowledge_check(text, jsonb),
  public.staff_reset_knowledge_check(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_knowledge_check(text), public.submit_knowledge_check(text, jsonb),
  public.staff_reset_knowledge_check(uuid, text), public.start_assessment(text) TO authenticated;
